 state.fiedlerSpectrumIndex=window.SpectralCourse.clampSpectrumIndex(state.fiedlerSpectrumIndex,count);const i=state.fiedlerSpectrumIndex;
 el.innerHTML=count?`<div class="eigenvalue-row selected"><span class="eigen-symbol">λ${subscript(i+1)}</span><strong>${fmt(r.values[i],5)}</strong><span class="eigen-meaning">${spectrumMeaning(r,i)}</span></div>`:`<p class="panel-description">${t('emptyShared')}</p>`;
