 let coordinates=`<line x1="35" y1="28" x2="525" y2="28" stroke="#627798"/><text x="35" y="60" fill="#b2c4dd" font-size="13">${fmt(-max,2)}</text><text x="280" y="60" text-anchor="middle" fill="#b2c4dd" font-size="13">0</text><text x="525" y="60" text-anchor="end" fill="#b2c4dd" font-size="13">${fmt(max,2)}</text>`;
 v.forEach((value,i)=>{const x=35+(value+max)/(2*max)*490,y=14+(i%4)*8;coordinates+=`<circle cx="${x}" cy="${y}" r="4" fill="${color(value,max)}"><title>${t('node')} ${i+1}: ${fmt(value,5)}</title></circle>`;});
 if(state.module==='fiedler'&&g.result.components.length===1&&Math.abs(state.threshold)<=max){const x=35+(state.threshold+max)/(2*max)*490;coordinates+=`<line x1="${x}" y1="5" x2="${x}" y2="45" stroke="#efdaad" stroke-dasharray="3 3"/>`;}
