function renderSharedClustering(){
 const c=state.cluster,r=window.LabSession.clusterShared(M,state);c.result=r;
 $('workspace').innerHTML=`<section class="cluster-controls"><div class="control-bar">${sourcePicker()}${select('cluster-laplacian','laplacian',lapOptions,state.type)}<div class="field"><label for="cluster-k">${t('clusters')} k</label><select id="cluster-k">${[2,3,4,5,6].map(k=>option(String(k),String(c.k),String(k))).join('')}</select></div><a class="secondary-btn" href="#foundations">${t('graph')} ↗</a></div></section><p class="section-description">${t('sharedClusterNote')}</p>
 <div class="two-col"><section class="panel">${header(t('originalKmeans'))}<div class="graph-stage">${svg('','0 0 720 360','graph-svg','shared-kmeans-plot')}</div></section><section class="panel">${header(t('spectralClustering'))}<div class="graph-stage">${svg('','0 0 720 360','graph-svg','shared-spectral-plot')}</div></section></div>
 <div class="below-grid"><section class="panel">${header(t('embedding'))}${svg('','0 0 540 290','scatter-svg','embedding-plot')}<p class="panel-description">${t('embeddingNote')}</p></section><section class="panel">${header(t('eigenList'))}<div class="eigenvalue-list" id="cluster-spectrum"></div></section></div><p class="control-explanation">${r.analysis.components.length>r.k?t('tooManyComponents'):state.graph.nodes.length<c.k?t('sharedSmallCluster'):t('sameData')}</p>`;
 sharedPlot('shared-kmeans-plot',r.original.labels);sharedPlot('shared-spectral-plot',r.spectral.labels);
 if(r.embedding.length)scatter('embedding-plot',r.embedding.map(p=>[p[0],p[1]||0]),r.spectral.labels);
 drawSpectrum(r.analysis,r.k-1,'cluster-spectrum');
 bindSourcePicker();$('cluster-k').onchange=e=>{c.k=+e.target.value;saveState();renderSharedClustering();};$('cluster-laplacian').onchange=e=>{window.LabSession.setType(state,e.target.value);saveState();renderSharedClustering();};
}

function renderClustering(){clearTimeout(scheduleCluster.timer);const c=state.cluster;if(c.source==='shared'){renderSharedClustering();return;}
 $('workspace').innerHTML=`<section class="cluster-controls"><div class="control-bar">${sourcePicker()}${select('cluster-dataset','dataset',['moons','circles','blobs'],c.dataset)}${select('cluster-method','construction',['knn','epsilon','gaussian'],c.method)}<div class="field"><label for="cluster-k">${t('clusters')}</label><select id="cluster-k">${[2,3,4,5,6].map(k=>option(String(k),String(c.k),String(k))).join('')}</select></div>${select('cluster-laplacian','laplacian',lapOptions,c.type)}<div class="field"><label for="cluster-neighbors">${t('neighbors')} <output id="neighbors-output">${c.neighbors}</output></label><input id="cluster-neighbors" type="range" min="2" max="20" step="1" value="${c.neighbors}" ${c.method!=='knn'?'disabled':''}></div><div class="field"><label for="cluster-sigma">${t('sigma')} <output id="sigma-output">${fmt(c.sigma,3)}</output></label><input id="cluster-sigma" type="range" min=".001" max="${Math.max(1.2,c.sigma*1.2,(M.recommendSigma(c.points)||1)*5)}" step=".001" value="${c.sigma}"></div>${c.method==='epsilon'?`<div class="field"><label for="cluster-epsilon">${t('radius')} <output id="epsilon-output">${fmt(c.epsilon,2)}</output></label><input id="cluster-epsilon" type="range" min=".1" max="1.5" step=".01" value="${c.epsilon}"></div>`:''}<div class="field" style="max-width:100px;min-width:80px"><label for="cluster-seed">${t('seed')}</label><input id="cluster-seed" type="number" min="0" max="9999" step="1" value="${c.seed}"></div><button class="secondary-btn" id="reset-cluster">↻ ${t('reset')}</button></div>${recommendationControls('cluster')}<div class="cluster-update" id="cluster-update" role="status" aria-live="polite"></div></section><div class="two-col"><section class="panel">${header(`<span class="plot-number">01</span> ${t('original')}`)}${toolButtons(c,true)}${svg('','0 0 540 290','scatter-svg','original-plot')}<div class="plot-foot"><span>${t('clusterHint')}</span><span id="points-count"></span></div></section><section class="panel">${header(`<span class="plot-number">02</span> ${t('similarity')}`,'')}${svg('','0 0 540 290','scatter-svg','similarity-plot')}<div class="plot-foot"><span id="similarity-info"></span></div></section></div><div class="flow-line"><b>${t('original')}</b><span>→</span><b>${t('similarity')}</b><span>→</span><b>${t('embedding')}</b><span>→</span><b>K-Means</b></div><div class="two-col"><section class="panel">${header(t('originalKmeans'),'')}${svg('','0 0 540 290','scatter-svg','kmeans-plot')}<div class="plot-foot">${t('sameData')}</div></section><section class="panel">${header(t('spectralClustering'),'')}${svg('','0 0 540 290','scatter-svg','spectral-plot')}<div class="plot-foot" id="spectral-cluster-info"></div></section></div><div class="below-grid"><section class="panel">${header(t('embedding'))}${svg('','0 0 540 240','scatter-svg','embedding-plot')}<div class="plot-foot">${t('embeddingNote')}</div></section><section class="panel">${header(t('spectrum'))}<div class="spectrum-wrap"><div class="eigenvalue-list" id="cluster-spectrum"></div></div><div class="stat-note" id="cluster-warning"></div></section></div>${observation('obsCluster')}`;
 $('cluster-dataset').onchange=e=>{c.dataset=e.target.value;c.points=M.dataset(c.dataset,80,c.seed);Object.assign(c,M.recommendGraph(c.points));renderClustering();};$('cluster-method').onchange=e=>{c.method=e.target.value;renderClustering();};$('cluster-k').onchange=e=>{c.k=+e.target.value;updateCluster();};$('cluster-laplacian').onchange=e=>{window.LabSession.setType(state,e.target.value);updateCluster();};
 for(const [id,key]of [['neighbors','neighbors'],['sigma','sigma'],['epsilon','epsilon']])if($('cluster-'+id))$('cluster-'+id).oninput=e=>{c[key]=+e.target.value;$(id+'-output').textContent=key==='neighbors'?c[key]:fmt(c[key],3);scheduleCluster();};
 $('cluster-seed').onchange=e=>{const seed=+e.target.value;if(!Number.isInteger(seed)||seed<0||seed>9999){e.target.value=c.seed;return;}c.seed=seed;c.points=M.dataset(c.dataset,c.points.length,c.seed);updateCluster();};$('reset-cluster').onclick=()=>{c.points=M.dataset(c.dataset,80,c.seed);updateCluster();};document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>{c.tool=b.dataset.tool;renderClustering();});updateCluster();bindScatter();bindSourcePicker();bindRecommendation('cluster',()=>renderClustering());
}
function scheduleCluster(){clearTimeout(scheduleCluster.timer);scheduleCluster.timer=setTimeout(()=>{if(state.module==='clustering'&&state.cluster.source==='geometry'&&$('original-plot'))updateCluster();},90);}
function bounds(points){const xs=points.map(p=>p[0]),ys=points.map(p=>p[1]||0);let loX=Math.min(...xs),hiX=Math.max(...xs),loY=Math.min(...ys),hiY=Math.max(...ys);const midX=(loX+hiX)/2,midY=(loY+hiY)/2,span=Math.max((hiX-loX)/1.8,hiY-loY,.01)*1.22;return {loX:midX-span*.9,hiX:midX+span*.9,loY:midY-span*.5,hiY:midY+span*.5};}
function pointMap(p,b){return [36+(p[0]-b.loX)/(b.hiX-b.loX)*468,260-(p[1]-b.loY)/(b.hiY-b.loY)*228];}
function scatter(id,points,labels,A,b= bounds(points),interactive=false){const positions=points.map(p=>pointMap(p,b));let body='<path d="M36 28V260H510" fill="none" stroke="#304b70"/><text x="513" y="276" fill="#7e98bd" font-size="10">x₁</text><text x="20" y="28" fill="#7e98bd" font-size="10">x₂</text>';
 if(A)for(let i=0;i<A.length;i++)for(let j=i+1;j<A.length;j++)if(A[i][j]>.01)body+=`<line x1="${positions[i][0]}" y1="${positions[i][1]}" x2="${positions[j][0]}" y2="${positions[j][1]}" stroke="#6d8fca" stroke-opacity="${Math.min(.35,A[i][j]*.38)}" stroke-width=".6"/>`;
 positions.forEach((p,i)=>{body+=`<circle ${interactive?`data-point="${i}" tabindex="0" role="button"`:''} cx="${p[0]}" cy="${p[1]}" r="${A?3.1:4.2}" fill="${labels?palette[labels[i]%palette.length]:'#9ebafa'}" stroke="#101f39" stroke-width=".7" aria-label="${t('node')} ${i+1}"><title>${i+1}: (${fmt(points[i][0],2)}, ${fmt(points[i][1],2)})</title></circle>`;});$(id).innerHTML=id==='embedding-plot'?body.replace('>x₁<','>z₁<').replace('>x₂<','>z₂<'):body;
}
function updateCluster(){clearTimeout(scheduleCluster.timer);saveState();const c=state.cluster,previous=c.result?.spectral.labels;c.result=M.cluster(c.points,c);c.bounds=bounds(c.points);const r=c.result;scatter('original-plot',c.points,null,null,c.bounds,true);scatter('similarity-plot',c.points,null,r.analysis.A,c.bounds);scatter('kmeans-plot',c.points,r.original.labels,null,c.bounds);scatter('spectral-plot',c.points,r.spectral.labels,null,c.bounds);const display=r.embedding.map(p=>[p[0],p[1]||0]);scatter('embedding-plot',display,r.spectral.labels);$('embedding-plot').setAttribute('viewBox','0 0 540 290');$('points-count').textContent=`${c.points.length} ${t('points')}`;const n=r.analysis.components.length;$('similarity-info').textContent=`${n} ${t('components')} · λ₂ = ${fmt(r.analysis.values[1],6)}`;$('spectral-cluster-info').innerHTML=Array.from({length:c.k},(_,i)=>`<span><i class="legend-dot" style="background:${palette[i]}"></i> ${i+1}: ${r.spectral.labels.filter(l=>l===i).length}</span>`).join('');$('cluster-warning').textContent=n>c.k?t('tooManyComponents'):n>1?t('clusterDisconnected'):t('mathClusterP2');drawSpectrum(r.analysis,c.k-1,'cluster-spectrum');const rec=M.recommendSigma(c.points);$('cluster-recommendation-value').textContent=rec===null?'—':fmt(rec,3);$('cluster-update').textContent=t('recomputed')+' · '+t(previous?(M.samePartition(previous,r.spectral.labels)?'partitionUnchanged':'partitionChanged'):'resultReady');if(c.method==='gaussian'&&rec&&c.sigma>3*rec)$('cluster-warning').textContent=t('broadSigmaWarning');}
function bindScatter(){const el=$('original-plot'),c=state.cluster;let drag=null;const coords=e=>{const p=el.createSVGPoint();p.x=e.clientX;p.y=e.clientY;const q=p.matrixTransform(el.getScreenCTM().inverse()),b=drag?.bounds||c.bounds;return [b.loX+(q.x-36)/468*(b.hiX-b.loX),b.loY+(260-q.y)/228*(b.hiY-b.loY)];};
 el.onpointerdown=e=>{const target=e.target.closest('[data-point]');if(target){const i=+target.dataset.point;if(c.tool==='remove'){if(c.points.length<=8){toast(t('maxPoints'));return;}c.points.splice(i,1);updateCluster();}else{drag={i,bounds:{...c.bounds}};el.setPointerCapture(e.pointerId);}}else if(c.tool==='addNode'){if(c.points.length>=120){toast(t('maxPoints'));return;}c.points.push(coords(e));updateCluster();}};
 el.onpointermove=e=>{if(drag){c.points[drag.i]=coords(e);scatter('original-plot',c.points,null,null,drag.bounds,true);}};el.onpointerup=el.onpointercancel=()=>{if(drag){drag=null;updateCluster();}};el.onkeydown=e=>{const target=e.target.closest('[data-point]');if(!target)return;const i=+target.dataset.point;if(e.key==='Delete'&&c.points.length>8){c.points.splice(i,1);updateCluster();}else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();c.points[i][0]+=e.key==='ArrowLeft'?-.03:e.key==='ArrowRight'?.03:0;c.points[i][1]+=e.key==='ArrowDown'?-.03:e.key==='ArrowUp'?.03:0;updateCluster();el.querySelector(`[data-point="${i}"]`).focus();}};
}
const meshCache=new Map();
function prepareMesh(){
 const s=state.mesh;
 if(s.kind==='shared'){
   const g=state.graph,data={vertices:g.nodes.map(p=>[(p.x-360)/125,(180-p.y)/125,0]),faces:[]};
   s.computed={data,edges:g.edges,result:M.analyze(g.nodes,g.edges,state.type)};return;
 }
 const key=s.kind+':'+s.type;
 if(!meshCache.has(key)){const data=s.kind==='bunny'?window.SpectralMeshes.bunny:M.mesh(s.kind),edges=M.meshEdges(data),result=M.analyze(data.vertices,edges,s.type,data.modes?.[s.type==='unnormalized'?'unnormalized':'symmetric']||null);meshCache.set(key,{data,edges,result});}
 s.computed=meshCache.get(key);
}
function renderMesh(){const s=state.mesh;prepareMesh();const {data}=s.computed;s.index=Math.max(0,Math.min(s.index,data.vertices.length-1));
 $('workspace').innerHTML=`<div class="lab-grid mesh-grid"><section class="panel">${header(t('meshPlot'),'')}<div class="control-bar">${select('mesh-model','meshChoice',['shared','torus','sphere','grid',...(window.SpectralMeshes.bunny?['bunny']:[])],s.kind)}${select('mesh-laplacian','laplacian',lapOptions,s.type)}<button class="secondary-btn" id="mesh-reset">↻ ${t('reset')}</button></div><div class="graph-stage"><div class="stage-corner"><span class="tag" id="mesh-mode-tag"></span><span class="tag">3D</span></div><canvas id="mesh-canvas" class="mesh-canvas" tabindex="0" role="img" aria-label="${t('meshPlot')}. ${t('rotateHint')}"></canvas></div><div class="graph-bottom"><span>${t('rotateHint')}</span><label><input id="mesh-wire" type="checkbox" ${s.wire?'checked':''}> ${t('wireframe')}</label></div></section><aside class="panel stat-panel">${header(t('spectralInfo'))}<div class="mesh-readout"><div class="stat-title">${t('frequency')}</div><div class="stat-value"><span class="lambda" id="mesh-lambda-label"></span><strong id="mesh-lambda"></strong></div><span class="stat-badge" id="mesh-frequency"></span></div><div class="slider-section"><div class="range-row"><label for="mesh-index">${t('modeIndex')}</label><output id="mesh-index-value"></output></div><div class="eigen-picker-controls"><button class="small-btn" id="mesh-prev" aria-label="${t('prevMode')}">←</button><select id="mesh-index">${s.computed.result.values.slice(0,30).map((value,i)=>option(String(i+1),String(s.index+1),`v${subscript(i+1)} · λ = ${fmt(value,4)}`)).join('')}</select><button class="small-btn" id="mesh-next" aria-label="${t('nextMode')}">→</button></div></div><div class="stat-grid"><div class="stat-cell"><small>${t('nodes')}</small><b>${data.vertices.length}</b></div><div class="stat-cell"><small>${t('faces')}</small><b>${data.faces.length}</b></div></div><div class="slider-section"><div class="range-row"><span>${t('energy')} fᵀ${s.type==='unnormalized'?'L':'L₀'}f</span><output id="mesh-energy"></output></div></div><div class="stat-note">${t(s.kind==='shared'?'eigenDefinition':'meshMethod')}</div></aside></div><div class="mesh-legend"><span>${t('negative')}</span><span class="gradient-legend"></span><span>${t('positive')}</span></div><div class="source-note">${s.kind==='shared'?t('sharedMeshNote'):s.kind==='bunny'?`${t('bunnySource')} · <a href="https://graphics.stanford.edu/data/3Dscanrep/" target="_blank" rel="noopener">${t('sourceLink')}</a>`:t('syntheticSource')}</div><div id="mesh-repeat" class="repeat-note"></div>${observation('obsMesh')}`;
 $('mesh-model').onchange=e=>{s.kind=e.target.value;s.index=1;s.rotation=s.kind==='shared'?[0,0]:s.kind==='bunny'?[-.1,.15]:[.8,.2];s.zoom=1;renderMesh();};$('mesh-laplacian').onchange=e=>{window.LabSession.setType(state,e.target.value);saveState();renderMesh();};$('mesh-index').onchange=e=>{s.index=+e.target.value-1;updateMesh();};$('mesh-prev').onclick=()=>{s.index=Math.max(0,s.index-1);updateMesh();};$('mesh-next').onclick=()=>{s.index=Math.min(Math.min(30,data.vertices.length)-1,s.index+1);updateMesh();};$('mesh-wire').onchange=e=>{s.wire=e.target.checked;saveState();drawMesh();};$('mesh-reset').onclick=()=>{s.rotation=s.kind==='shared'?[0,0]:s.kind==='bunny'?[-.1,.15]:[.8,.2];s.zoom=1;s.index=1;$('mesh-index').value=2;updateMesh();};bindMesh();updateMesh();
}
function updateMesh(){saveState();const s=state.mesh,r=s.computed.result;$('mesh-index-value').textContent=`${r.values.length?s.index+1:0} / ${Math.min(30,r.values.length)}`;$('mesh-lambda-label').textContent='λ'+subscript(s.index+1);$('mesh-lambda').textContent=fmt(r.values[s.index]);$('mesh-mode-tag').textContent='v'+subscript(s.index+1);$('mesh-energy').textContent=fmt(M.energy(r.A,r.vectors[s.index]||[]));$('mesh-frequency').textContent=`${t(s.index<10?'low':'high')} · ${t('vector')} ${s.index+1}`;const repeated=r.values.some((v,i)=>i!==s.index&&Math.abs(v-r.values[s.index])<r.tolerance);$('mesh-repeat').textContent=repeated?t('repeated'):'';$('mesh-repeat').hidden=!repeated;$('mesh-index').disabled=!r.values.length;$('mesh-index').value=String(s.index+1);$('mesh-prev').disabled=s.index<=0;$('mesh-next').disabled=s.index>=Math.min(30,r.values.length)-1;if(!r.values.length)$('mesh-frequency').textContent=t('emptyShared');drawMesh();}
function drawMesh(){const el=$('mesh-canvas');if(!el)return;const s=state.mesh,{data,result}=s.computed,dpr=Math.min(window.devicePixelRatio||1,2),rect=el.getBoundingClientRect();el.width=Math.round(rect.width*dpr);el.height=Math.round(rect.height*dpr);const ctx=el.getContext('2d');ctx.scale(dpr,dpr);const w=rect.width,h=rect.height,scale=Math.min(w,h)*.23*s.zoom,cx=w/2,cy=h/2+3,[rx,ry]=s.rotation;
 const positions=data.vertices.map(([x,y,z])=>{const yy=y*Math.cos(rx)-z*Math.sin(rx),zz=y*Math.sin(rx)+z*Math.cos(rx),xx=x*Math.cos(ry)+zz*Math.sin(ry),depth=-x*Math.sin(ry)+zz*Math.cos(ry);return [cx+xx*scale,cy-yy*scale,depth];});
 const v=result.vectors[s.index]||[],max=Math.max(...v.map(Math.abs),.001);const ordered=data.faces.map(f=>({f,z:f.reduce((sum,i)=>sum+positions[i][2],0)/3})).sort((a,b)=>a.z-b.z);
 if(s.kind==='shared'){
   for(const e of s.computed.edges){if(e.w<=0)continue;const a=positions[e.a],b=positions[e.b];ctx.strokeStyle='#6d88b1';ctx.lineWidth=1.3;ctx.beginPath();ctx.moveTo(a[0],a[1]);ctx.lineTo(b[0],b[1]);ctx.stroke();}
   positions.forEach((p,i)=>{ctx.fillStyle=color(v[i]||0,max);ctx.beginPath();ctx.arc(p[0],p[1],8,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d4dfef';ctx.font='14px Segoe UI';ctx.textAlign='center';ctx.fillText(String(i+1),p[0],p[1]-17);});
 }
 if(!data.vertices.length){ctx.fillStyle='#b9cbe3';ctx.font='15px Segoe UI';ctx.textAlign='center';ctx.fillText(t('emptyShared'),w/2,h/2);return;}
 ctx.lineJoin='round';for(const {f}of ordered){const p=f.map(i=>positions[i]);ctx.beginPath();ctx.moveTo(p[0][0],p[0][1]);ctx.lineTo(p[1][0],p[1][1]);ctx.lineTo(p[2][0],p[2][1]);ctx.closePath();const value=f.reduce((sum,i)=>sum+v[i],0)/3;ctx.fillStyle=color(value,max);ctx.fill();if(s.wire){ctx.strokeStyle='#0b224e66';ctx.lineWidth=.55;ctx.stroke();}}
 ctx.fillStyle='#819abf';ctx.font='10px Segoe UI';ctx.fillText('x',w-42,h-25);ctx.fillText('y',w-61,h-54);ctx.strokeStyle='#6888b6';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(w-62,h-30);ctx.lineTo(w-46,h-30);ctx.moveTo(w-62,h-30);ctx.lineTo(w-62,h-48);ctx.stroke();
}
function bindMesh(){const el=$('mesh-canvas'),s=state.mesh;let drag=null;el.onpointerdown=e=>{drag=[e.clientX,e.clientY];el.setPointerCapture(e.pointerId);};el.onpointermove=e=>{if(drag){s.rotation[1]+=(e.clientX-drag[0])*.009;s.rotation[0]+=(e.clientY-drag[1])*.009;drag=[e.clientX,e.clientY];drawMesh();}};el.onpointerup=el.onpointercancel=()=>{drag=null;saveState();};el.addEventListener('wheel',e=>{e.preventDefault();s.zoom=Math.max(.5,Math.min(2,s.zoom-e.deltaY*.001));drawMesh();saveState();},{passive:false});el.onkeydown=e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();s.rotation[1]+=e.key==='ArrowLeft'?-.1:e.key==='ArrowRight'?.1:0;s.rotation[0]+=e.key==='ArrowUp'?-.1:e.key==='ArrowDown'?.1:0;drawMesh();}};}
function renderMath(){
 if(['smoothness','variational','fourier','convolution'].includes(state.module))return;
 if(state.module==='foundations'){$('math-section').innerHTML='';return;}
 const mod=state.module,prefix=mod==='playground'?'Graph':mod==='fiedler'?'Fiedler':mod==='clustering'?'Cluster':'Mesh';
 const formulas=mod==='playground'?['L_0=D-A',String.raw`0=\lambda_1\leq\lambda_2\leq\cdots\leq\lambda_n`,String.raw`A\longrightarrow L\longrightarrow(\lambda_r,v_r)`]:mod==='fiedler'?[String.raw`f^{\mathsf T}L_0f=\sum_{\{i,j\}\in E}w_{ij}(f_i-f_j)^2`,String.raw`\lambda_2(L_0)=\min_{f\perp\mathbf1,\,\lVert f\rVert=1} f^{\mathsf T}L_0f`,String.raw`C_1=\{i:v_2(i)<t\}`]:mod==='clustering'?[String.raw`w_{ij}=\exp\!\left(-\frac{\lVert x_i-x_j\rVert^2}{2\sigma^2}\right)`,String.raw`U=[v_1,\ldots,v_k]`,String.raw`x_i\longrightarrow z_i\longrightarrow\mathrm{cluster}`]:[String.raw`L v_r=\lambda_r v_r`,String.raw`v_r^{\mathsf T}L_0v_r=\lambda_r(L_0)`,String.raw`-\Delta\varphi=\lambda\varphi`];
 $('math-section').innerHTML=`<div class="math-heading"><span>✧</span><h3>${t('mathTitle')}</h3></div><div class="math-cards">${[1,2,3].map((n,i)=>`<article class="math-card"><span class="step">0${n} / ${t(['definition','intuition','connection'][i]).replace(/^0[123] \/ /,'')}</span><h4>${t(`math${prefix}${n}`)}</h4><div class="formula">${tex(formulas[i],true)}</div><p>${t(`math${prefix}P${n}`)}</p></article>`).join('')}</div>`;
 window.LabNotation.typeset($('math-section'));
}
